const s=(t,r="USD")=>new Intl.NumberFormat("en-US",{style:"currency",currency:r}).format(t),i=t=>t?new Date(t).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric",hour:"2-digit",minute:"2-digit"}):"N/A",u=t=>{if(!t)return"";const r=new Date(t),e=new Date-r,n=Math.floor(e/6e4),o=Math.floor(n/60),a=Math.floor(o/24);return n<1?"Just now":n<60?`${n}m ago`:o<24?`${o}h ago`:`${a}d ago`};export{i as a,u as b,s as f};
